{
  "iteration": 4,
  "pcvs": [
    {
      "name": "logit_elements",
      "expression": "logits.numel()",
      "rationale": "Captures baseline work proportional to batch and vocabulary size."
    },
    {
      "name": "random_logit_elements",
      "expression": "logits.numel() if not sampling_metadata.all_greedy else 0",
      "rationale": "Captures steady-state stochastic sampling work."
    },
    {
      "name": "penalized_logit_elements",
      "expression": "logits.numel() if not sampling_metadata.no_penalties else 0",
      "rationale": "Captures vocabulary-wide penalty processing."
    },
    {
      "name": "cold_dynamo_sampling",
      "expression": "int(not sampling_metadata.all_greedy and sum(len(torch._dynamo.eval_frame._debug_get_cache_entry_list(getattr(f, '_torchdynamo_orig_callable'))) for f in self.topk_topp_sampler.forward_cpu.__func__.__globals__.values() if getattr(f, '_torchdynamo_orig_callable', None) is not None) == 0)",
      "rationale": "Uses the cardinality of existing Dynamo cache entries for compiled sampling helpers to identify cold sampling."
    }
  ],
  "hypothesis": "Dynamo cache state may isolate initial compilation even when the selected backend leaves the Inductor cache empty."
}
